import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

enum ReservationStatus { PENDING, COMMITTED, CANCELLED, EXPIRED }

class Bin {
    final String sku; final String warehouseId;
    int onHand; int reserved;
    final ReentrantLock lock = new ReentrantLock();
    Bin(String sku, String w, int q) { this.sku = sku; this.warehouseId = w; this.onHand = q; }
    int available() { return onHand - reserved; }
}

class Reservation {
    final String id; final String sku; final String warehouseId;
    final int qty; final long expiresAt;
    volatile ReservationStatus status = ReservationStatus.PENDING;
    Reservation(String id, String sku, String w, int qty, long ttlMs) {
        this.id = id; this.sku = sku; this.warehouseId = w; this.qty = qty;
        this.expiresAt = System.currentTimeMillis() + ttlMs;
    }
}

interface StockListener { void onLowStock(String sku, String warehouseId, int available); }

public class InventoryService {
    private final Map<String, Bin> bins = new ConcurrentHashMap<>();
    private final Map<String, Reservation> reservations = new ConcurrentHashMap<>();
    private final List<StockListener> listeners = new CopyOnWriteArrayList<>();
    private final int lowStockThreshold;
    private final ScheduledExecutorService sweeper = Executors.newSingleThreadScheduledExecutor();
    public InventoryService(int lowStockThreshold) {
        this.lowStockThreshold = lowStockThreshold;
        sweeper.scheduleAtFixedRate(this::expireSweep, 1, 1, TimeUnit.SECONDS);
    }
    private String key(String sku, String w) { return sku + "#" + w; }
    public void addStock(String sku, String w, int qty) {
        if (qty <= 0) throw new IllegalArgumentException("qty must be positive");
        Bin b = bins.computeIfAbsent(key(sku, w), k -> new Bin(sku, w, 0));
        b.lock.lock();
        try { b.onHand += qty; } finally { b.lock.unlock(); }
    }
    public String reserve(String sku, String w, int qty, long ttlMs) {
        Bin b = bins.get(key(sku, w));
        if (b == null || qty <= 0) return null;
        b.lock.lock();
        try {
            if (b.available() < qty) return null; // atomic check-and-hold
            b.reserved += qty;
            String id = UUID.randomUUID().toString();
            reservations.put(id, new Reservation(id, sku, w, qty, ttlMs));
            if (b.available() <= lowStockThreshold)
                listeners.forEach(l -> l.onLowStock(sku, w, b.available()));
            return id;
        } finally { b.lock.unlock(); }
    }
    public boolean commit(String reservationId) {
        Reservation r = reservations.get(reservationId);
        if (r == null || r.status != ReservationStatus.PENDING) return false;
        Bin b = bins.get(key(r.sku, r.warehouseId));
        b.lock.lock();
        try {
            if (r.status != ReservationStatus.PENDING) return false;
            if (System.currentTimeMillis() > r.expiresAt) { r.status = ReservationStatus.EXPIRED; b.reserved -= r.qty; return false; }
            b.reserved -= r.qty; b.onHand -= r.qty; r.status = ReservationStatus.COMMITTED;
            return true;
        } finally { b.lock.unlock(); }
    }
    public boolean cancel(String reservationId) {
        Reservation r = reservations.get(reservationId);
        if (r == null || r.status != ReservationStatus.PENDING) return false;
        Bin b = bins.get(key(r.sku, r.warehouseId));
        b.lock.lock();
        try {
            if (r.status != ReservationStatus.PENDING) return false;
            b.reserved -= r.qty; r.status = ReservationStatus.CANCELLED;
            return true;
        } finally { b.lock.unlock(); }
    }
    private void expireSweep() {
        long now = System.currentTimeMillis();
        for (Reservation r : reservations.values()) {
            if (r.status == ReservationStatus.PENDING && now > r.expiresAt) {
                Bin b = bins.get(key(r.sku, r.warehouseId));
                if (b == null) continue;
                b.lock.lock();
                try { if (r.status == ReservationStatus.PENDING) { r.status = ReservationStatus.EXPIRED; b.reserved -= r.qty; } }
                finally { b.lock.unlock(); }
            }
        }
    }
    public int available(String sku, String w) {
        Bin b = bins.get(key(sku, w));
        if (b == null) return 0;
        b.lock.lock();
        try { return b.available(); } finally { b.lock.unlock(); }
    }
}

import threading, time, uuid
class Bin:
    def __init__(self, qty=0):
        self.on_hand = qty; self.reserved = 0; self.lock = threading.Lock()
    @property
    def available(self): return self.on_hand - self.reserved
class Inventory:
    def __init__(self): self.bins, self.holds = {}, {}
    def add_stock(self, sku, w, qty):
        b = self.bins.setdefault((sku, w), Bin())
        with b.lock: b.on_hand += qty
    def reserve(self, sku, w, qty, ttl=300):
        b = self.bins.get((sku, w))
        if not b: return None
        with b.lock:
            if b.available < qty: return None
            b.reserved += qty
            rid = str(uuid.uuid4())
            self.holds[rid] = (b, qty, time.time() + ttl, 'PENDING')
            return rid
    def commit(self, rid):
        rec = self.holds.get(rid)
        if not rec or rec[3] != 'PENDING': return False
        b, qty, exp, _ = rec
        with b.lock:
            if time.time() > exp:
                b.reserved -= qty; self.holds[rid] = (b, qty, exp, 'EXPIRED'); return False
            b.reserved -= qty; b.on_hand -= qty
            self.holds[rid] = (b, qty, exp, 'COMMITTED'); return True
